715	// ---- 持久化 ----
716	
717	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
718	func (s *Store) loadLocked() (*storedState, error) {
719		raw, err := os.ReadFile(s.path)
720		if err != nil {
721			return nil, err
722		}
723		if len(bytes.TrimSpace(raw)) == 0 {
724			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
725		}
726		if err := checkStateStructure(raw); err != nil {
727			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
728		}
729		var state storedState
730		dec := json.NewDecoder(bytes.NewReader(raw))
731		dec.DisallowUnknownFields()
732		if err := dec.Decode(&state); err != nil {
733			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
734		}
735		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
736		var extra json.RawMessage
737		if err := dec.Decode(&extra); err != io.EOF {
738			if err == nil {
739				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
740			}
741			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
742		}
743		if err := validateState(&state); err != nil {
744			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
745		}
746		return &state, nil
747	}
748	
749	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
750	// 任一步失败都保留上次完整状态。调用方必须持锁。
751	func (s *Store) commitLocked(state *storedState) error {
752		if err := validateState(state); err != nil {
753			return fmt.Errorf("refusing to persist invalid state: %w", err)
754		}
755		payload, err := json.MarshalIndent(state, "", "  ")
756		if err != nil {
757			return err
758		}
759		payload = append(payload, '\n')
760	
761		dir := filepath.Dir(s.path)
762		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
763		if err != nil {
764			return err
765		}
766		tmpName := tmp.Name()
767		cleanup := func() { _ = os.Remove(tmpName) }
768		if _, err := tmp.Write(payload); err != nil {
769			_ = tmp.Close()
770			cleanup()
771			return err
772		}
773		if err := tmp.Sync(); err != nil {
774			_ = tmp.Close()
775			cleanup()
776			return err
777		}
778		if err := tmp.Close(); err != nil {
779			cleanup()
780			return err
781		}
782		if err := os.Chmod(tmpName, 0o600); err != nil {
783			cleanup()
784			return err
785		}
786		if err := os.Rename(tmpName, s.path); err != nil {
787			cleanup()
788			return err
789		}
790		if err := syncDir(dir); err != nil {
791			return err
792		}
793		return nil
794	}
795	
796	func syncDir(dir string) error {
797		d, err := os.Open(dir)
798		if err != nil {
799			return err
800		}
801		defer d.Close()
802		return d.Sync()
803	}
804	
805	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
806	func validateState(state *storedState) error {
807		if state.Magic != stateMagic {
808			return fmt.Errorf("bad magic %q", state.Magic)
809		}
810		if state.Version != stateVersion {
811			return fmt.Errorf("unsupported state version %d", state.Version)
812		}
813		if state.InitialTreasury < 0 {
814			return errors.New("initial treasury balance is negative")
815		}
816		if state.Treasury < 0 {
817			return errors.New("treasury balance is negative")
818		}
819		if state.Balances == nil {
820			return errors.New("balances table is missing")
821		}
822		if state.Proposals == nil {
823			return errors.New("proposals table is missing")
824		}
825		if state.Receipts == nil {
826			return errors.New("receipts table is missing")
827		}
828		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
829		if state.VoteProposals == nil {
830			state.VoteProposals = map[string]*storedVoteProposal{}
831		}
832		for account, balance := range state.Balances {
833			if account == "" {
834				return errors.New("balance entry with empty account")
835			}
836			if balance < 0 {
837				return fmt.Errorf("balance of %q is negative", account)
838			}
839		}
840		for key, p := range state.Proposals {
841			if p == nil {
842				return fmt.Errorf("proposal %q is empty", key)
843			}
844			if p.ID != key || p.ID == "" {
845				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
846			}
847			if p.State != "passed" && p.State != "executed" {
848				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
849			}
850			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
851		}
852		if err := validateVoteProposals(state); err != nil {
853			return err
854		}
855	
856		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
857		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
858		simTreasury := state.InitialTreasury
859		simBalances := map[string]int64{}
860		seenReceipts := map[string]int{}
861		for order, rcpt := range state.Receipts {
862			if rcpt == nil {
863				return fmt.Errorf("receipt %d is empty", order)
864			}
865			if rcpt.Order != order {
866				return fmt.Errorf("receipt %q order field is %d, expected %d", rcpt.ProposalID, rcpt.Order, order)
867			}
868			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
869				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
870			}
871			seenReceipts[rcpt.ProposalID] = order
872			ownerState, ownerTimelock, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
873			if !found {
874				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
875			}
876			if ownerState != "executed" {
877				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
878			}
879			// 保存的凭据与首次执行受同一条执行资格规则约束：executed_at 必须明确
880			// 写出且不得早于提案时间锁。登记提案与投票提案共用这一判断。
881			if err := validateReceiptExecutedAt(order, rcpt, ownerTimelock); err != nil {
882				return err
883			}
884			// 每项动作的四个余额字段（资金库/收款账户 × before/after）必须各自
885			// 明确写出：任何一个缺失、为 null 或类型不符都判整份状态损坏，不能
886			// 按转账金额、账户余额或其它凭据补出；明确写出的 0 是合法记录。
887			for i := range rcpt.Actions {
888				if err := validateReceiptActionBalances(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
889					return err
890				}
891			}
892			// 凭据声明的逐笔转账由统一转账规则（verifyReceiptTransfers）重放
893			// 核对：动作条数/编号/原文、资金库与收款账户前后余额任一不符都带
894			// 动作位置报损坏原因；本函数随即返回错误，整份状态被拒绝，重放结果
895			// 不会被查询或落盘采纳。
896			var verr error
897			simTreasury, verr = verifyReceiptTransfers(rcpt, ownerActions, simTreasury, simBalances)
898			if verr != nil {
899				return verr
900			}
901		}
902		if simTreasury != state.Treasury {
903			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
904		}
905		if len(simBalances) != len(state.Balances) {
906			return fmt.Errorf("balance table has %d accounts, receipt replay yields %d", len(state.Balances), len(simBalances))
907		}
908		for account, balance := range state.Balances {
909			if simBalances[account] != balance {
910				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
911			}
912		}
913		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
914		for _, p := range state.Proposals {
915			_, hasReceipt := seenReceipts[p.ID]
916			if p.State == "executed" && !hasReceipt {
917				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
918			}
919		}
920		for _, p := range state.VoteProposals {
921			_, hasReceipt := seenReceipts[p.ID]
922			if p.State == "executed" && !hasReceipt {
923				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
924			}
925		}
926		return nil
927	}
928	
929	// validateReceiptExecutedAt 严格判定一份已保存凭据的 executed_at：
930	// 字段未写出、显式为 null 或不是 int64 整数都返回带定位的错误；
931	// 明确写出的值必须不早于所属提案的 timelock_end（恰好等于时间锁有效，
932	// 时间锁允许 0 时明确写出的 0 同样有效）。order 是凭据在凭据表中的
933	// 位置（0 起），与提案编号一起用于定位。
934	// “缺失/空值/类型不符”的判定与逐票明细、计票结果共用同一份规则
935	// （requiredScalarProblem），此处只补充凭据的业务位置与执行资格检查。
936	func validateReceiptExecutedAt(order int, rcpt *Receipt, timelockEnd int64) error {
937		if problem := requiredScalarProblem(rcpt.executedAtRaw, scalarInteger); problem != "" {
938			return fmt.Errorf("receipt %d for proposal %q field %q %s", order, rcpt.ProposalID, "executed_at", problem)
939		}
940		if rcpt.ExecutedAt < timelockEnd {
941			return fmt.Errorf("receipt %d for proposal %q executed_at %d is before timelock_end %d",
942				order, rcpt.ProposalID, rcpt.ExecutedAt, timelockEnd)
943		}
944		return nil
945	}
946	
947	// validateReceiptActionBalances 严格判定一条动作留痕的四个余额字段：
948	// 资金库与收款账户两侧的 before/after 都必须明确写出、非 null 且为 int64
949	// 整数。任何一个字段缺失都判整份状态损坏，不能根据转账金额、账户余额或
950	// 其它凭据补出它——即使按其余记录推算该字段本来应为 0。明确写出的整数 0
951	// 是合法记录（如资金库恰好扣到 0、收款账户首次收款前为 0），不得当成缺失。
952	// index 是动作在凭据中的下标（0 起），与提案编号、所在侧一起用于定位。
953	// “缺失/空值/类型不符”的判定与逐票明细、计票结果、executed_at 共用同一份
954	// 规则（validateRawFields），此处只补充业务位置：提案编号 + 动作下标 + 侧。
955	func validateReceiptActionBalances(id string, index int, ar *ActionReceipt) error {
956		sides := []struct {
957			name   string
958			update *BalanceUpdate
959		}{
960			{"treasury", &ar.Treasury},
961			{"recipient", &ar.Recipient},
962		}
963		for _, side := range sides {
964			err := validateRawFields([]rawField{
965				{name: "before", kind: scalarInteger, raw: side.update.beforeRaw},
966				{name: "after", kind: scalarInteger, raw: side.update.afterRaw},
967			}, func(field, problem string) error {
968				return fmt.Errorf("receipt for proposal %q action %d %s field %q %s",
969					id, index, side.name, field, problem)
970			})
971			if err != nil {
972				return err
973			}
974		}
975		return nil
976	}
977	
978	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
979	
980	// schemaKind 是状态文件 JSON 在某一层的形状类别。
981	type schemaKind int
982	
983	const (
984		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
985		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
986		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
987		kindArray                     // 数组
988		kindString                    // 叶子：必须是 JSON 字符串
989		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
990		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
991	)
992	
993	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
994	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
995	type schemaNode struct {
996		kind   schemaKind
997		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
998		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
999	}
1000	
1001	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
1002	func schemaOf(t reflect.Type) *schemaNode {
1003		for t.Kind() == reflect.Pointer {
1004			t = t.Elem()
1005		}
1006		switch t.Kind() {
1007		case reflect.Struct:
1008			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
1009			for i := 0; i < t.NumField(); i++ {
1010				f := t.Field(i)
1011				if f.PkgPath != "" { // 未导出字段不参与 JSON
1012					continue
1013				}
1014				name := f.Name
1015				if tag, ok := f.Tag.Lookup("json"); ok {
1016					tagName, _, _ := strings.Cut(tag, ",")
1017					if tagName == "-" {
1018						continue
1019					}
1020					if tagName != "" {
1021						name = tagName
1022					}
1023				}
1024				node.fields[name] = schemaOf(f.Type)
1025			}
1026			return node
1027		case reflect.Map:
1028			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
1029		case reflect.Slice, reflect.Array:
1030			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
1031		case reflect.String:
1032			return &schemaNode{kind: kindString}
1033		case reflect.Bool:
1034			return &schemaNode{kind: kindBoolean}
1035		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
1036			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
1037			return &schemaNode{kind: kindInteger}
1038		default:
1039			return &schemaNode{kind: kindAny}
1040		}
1041	}
1042	
1043	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
1044	
1045	func init() {
1046		// 票据的四个标量字段（representative/weight/support/voted_at）由
1047		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
1048		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
1049		// 不抢在解码器之前用不含票据定位的通用信息报错。
1050		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
1051		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
1052			ballotFields[name].kind = kindAny
1053		}
1054		// 计票结果的两个权重字段（for_weight/against_weight）同理：缺失/空值/
1055		// 类型不符的判定需要带上提案编号，统一由 validateStoredTally 报错，
1056		// 结构扫描在这两个叶子位置保持宽松。tallied_at 保持严格整数叶子，
1057		// 其“不早于截止”的既有校验不变。
1058		tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
1059		for _, name := range []string{"for_weight", "against_weight"} {
1060			tallyFields[name].kind = kindAny
1061		}
1062		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
1063		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
1064		// 叶子位置保持宽松。
1065		storedStateSchema.fields["receipts"].elem.fields["executed_at"].kind = kindAny
1066		// 凭据逐笔留痕的四个余额字段（treasury/recipient 的 before/after）同理：
1067		// 缺失/空值/类型不符的判定需要带上提案编号、动作下标与所在侧，统一由
1068		// validateReceiptActionBalances 报错，结构扫描在这些叶子位置保持宽松。
1069		actionFields := storedStateSchema.fields["receipts"].elem.fields["actions"].elem.fields
1070		for _, side := range []string{"treasury", "recipient"} {
1071			balanceFields := actionFields[side].fields
1072			balanceFields["before"].kind = kindAny
1073			balanceFields["after"].kind = kindAny
1074		}
1075	}
1076	
1077	// scanFrame 是结构扫描的栈帧。
1078	type scanFrame struct {
1079		node    *schemaNode
1080		isArray bool
1081		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
1082		seen    map[string]bool
1083		atValue bool // 对象帧：下一个待消费 token 是值而非键
1084		index   int  // 数组帧：下一个元素下标
1085		path    string
1086	}
1087	
1088	func peekFrame(stack []*scanFrame) *scanFrame {
1089		if len(stack) == 0 {
1090			return nil
1091		}
1092		return stack[len(stack)-1]
1093	}
1094	
1095	// checkStateStructure 在解码前逐 token 扫描状态文件：
1096	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1097	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1098	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1099	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1100	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1101	//
1102	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1103	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1104	func checkStateStructure(raw []byte) error {
1105		dec := json.NewDecoder(bytes.NewReader(raw))
1106		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1107		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1108		dec.UseNumber()
1109		var stack []*scanFrame
1110		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1111		pendingNode := storedStateSchema
1112		pendingPath := "state"
1113	
1114		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1115		finishValue := func() {
1116			top := peekFrame(stack)
1117			if top == nil || top.opaque {
1118				return
1119			}
1120			if top.isArray {
1121				top.index++
1122			} else {
1123				top.atValue = false
1124			}
1125		}
1126	
1127		for {
1128			tok, err := dec.Token()
1129			if err == io.EOF {
1130				if len(stack) != 0 {
1131					return errors.New("unterminated object or array")
1132				}
1133				return nil
1134			}
1135			if err != nil {
1136				return err
1137			}
1138	
1139			if top := peekFrame(stack); top != nil && top.opaque {
1140				// 不透明容器内不做字段检查，只配对括号。
1141				if d, ok := tok.(json.Delim); ok {
1142					if d == '{' || d == '[' {
1143						stack = append(stack, &scanFrame{opaque: true})
1144					} else {
1145						stack = stack[:len(stack)-1]
1146						finishValue()
1147					}
1148				}
1149				continue
1150			}
1151	
1152			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1153				// 对象帧的键位置：闭括号或下一个键。
1154				if d, ok := tok.(json.Delim); ok {
1155					if d != '}' {
1156						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1157					}
1158					stack = stack[:len(stack)-1]
1159					finishValue()
1160					continue
1161				}
1162				key, ok := tok.(string)
1163				if !ok {
1164					return errors.New("object key must be a string")
1165				}
1166				if top.seen[key] {
1167					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1168				}
1169				top.seen[key] = true
1170				top.atValue = true
1171				switch top.node.kind {
1172				case kindObject:
1173					child, known := top.node.fields[key]
1174					if !known {
1175						return fmt.Errorf("unknown field %q at %s", key, top.path)
1176					}
1177					pendingNode = child
1178					pendingPath = top.path + "." + key
1179				case kindMap:
1180					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1181					pendingNode = top.node.elem
1182					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1183				}
1184				continue
1185			}
1186	
1187			// 值位置：对象键之后的值或数组元素。
1188			node := pendingNode
1189			path := pendingPath
1190			if top := peekFrame(stack); top != nil && top.isArray {
1191				node = top.node.elem
1192				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1193			}
1194			if d, ok := tok.(json.Delim); ok {
1195				switch d {
1196				case '{', '[':
1197					frame := &scanFrame{isArray: d == '[', path: path}
1198					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1199						(d == '[' && node.kind == kindArray)
1200					if !shapeOK {
1201						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1202						frame.opaque = true
1203					} else {
1204						frame.node = node
1205						if d == '{' {
1206							frame.seen = map[string]bool{}
1207						}
1208					}
1209					stack = append(stack, frame)
1210				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1211					if len(stack) == 0 {
1212						return errors.New("unexpected closing delimiter")
1213					}
1214					stack = stack[:len(stack)-1]
1215					finishValue()
1216				}
1217				continue
1218			}
1219			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1220			// null 不允许用来顶替字符串/布尔/整数。
1221			if err := checkLeafScalar(node, path, tok); err != nil {
1222				return err
1223			}
1224			finishValue()
1225		}
1226	}
1227	
1228	// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
1229	func leafKindName(k schemaKind) string {
1230		switch k {
1231		case kindString:
1232			return "string"
1233		case kindBoolean:
1234			return "boolean"
1235		case kindInteger:
1236			return "integer"
1237		default:
1238			return "value"
1239		}
1240	}
1241	
1242	// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
1243	func tokenKindName(tok json.Token) string {
1244		switch v := tok.(type) {
1245		case nil:
1246			return "null"
1247		case string:
1248			return "string"
1249		case bool:
1250			return "boolean"
1251		case json.Number:
1252			if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
1253				return "integer"
1254			}
1255			return "number"
1256		default:
1257			return "value"
1258		}
1259	}
1260	
1261	// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
1262	// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
1263	func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
1264		switch node.kind {
1265		case kindString, kindBoolean, kindInteger:
1266		default:
1267			return nil
1268		}
1269		if node.kind == kindInteger {
1270			if n, ok := tok.(json.Number); ok {
1271				if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
1272					return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
1273				}
1274				return nil
1275			}
1276		}
1277		want := leafKindName(node.kind)
1278		if got := tokenKindName(tok); got != want {
1279			return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
1280		}
1281		return nil
1282	}
1283

